import{_ as s,o as a,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const u=JSON.parse('{"title":"03 · TCP 可靠传输与拥塞控制","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/network/03.md","filePath":"bagu/network/03.md"}'),e={name:"bagu/network/03.md"};function l(p,t,r,i,d,g){return a(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="_03-·-tcp-可靠传输与拥塞控制" tabindex="-1">03 · TCP 可靠传输与拥塞控制 <a class="header-anchor" href="#_03-·-tcp-可靠传输与拥塞控制" aria-label="Permalink to &quot;03 · TCP 可靠传输与拥塞控制&quot;">​</a></h1><blockquote><p>握手只是&quot;搭好了线&quot;。这一篇讲<strong>线上怎么保证不丢、不乱、不把路堵死</strong>。 三个机制：确认重传（不丢）、滑动窗口（不乱 + 不浪费）、拥塞控制（不堵）。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>TCP 把&quot;不可靠的 IP 网络&quot;包装成&quot;可靠的字节流&quot;：<strong>每个字节编号、收到要确认、没确认就重传、发多少看窗口</strong>。</p><h2 id="生活类比-寄一箱书" tabindex="-1">生活类比：寄一箱书 <a class="header-anchor" href="#生活类比-寄一箱书" aria-label="Permalink to &quot;生活类比：寄一箱书&quot;">​</a></h2><table tabindex="0"><thead><tr><th>TCP 机制</th><th>寄书场景</th></tr></thead><tbody><tr><td>序号</td><td>每本书编号 1~100</td></tr><tr><td>确认号</td><td>收件人回&quot;我收到第 1~37 本了&quot;</td></tr><tr><td>超时重传</td><td>等太久没回音，重寄</td></tr><tr><td>快速重传</td><td>对方连说三次&quot;我只有前 37 本&quot;，说明 38 本丢了，立刻重寄</td></tr><tr><td>滑动窗口</td><td>收件人说&quot;我书架只放得下 20 本，你先寄 20 本&quot;</td></tr><tr><td>拥塞控制</td><td>快递公司说&quot;最近路上堵，你每天只能发 10 件&quot;</td></tr></tbody></table><p><strong>关键区别</strong>：<strong>滑动窗口是&quot;收件人&quot;限制的（怕你寄太快它收不下）；拥塞控制是&quot;路上&quot;限制的（怕把网络堵死）</strong>。这两个经常被混，面试常考。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、可靠传输的三根支柱" tabindex="-1">一、可靠传输的三根支柱 <a class="header-anchor" href="#一、可靠传输的三根支柱" aria-label="Permalink to &quot;一、可靠传输的三根支柱&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 序号：给每个字节编号，接收方靠它发现&quot;缺了哪一段&quot;</span></span>
<span class="line"><span>② 确认（ACK）：接收方告诉发送方&quot;我连续收到了前 N 个字节&quot;</span></span>
<span class="line"><span>③ 重传：发送方发现&quot;没被确认&quot;，就重发</span></span></code></pre></div><p><strong>注意 ACK 是累积确认</strong>：回 <code>ack=1001</code> 表示&quot;1~1000 我全收到了&quot;。这就意味着<strong>只要中间缺一段，后面的全都要等</strong>（队头阻塞）。</p><h3 id="二、重传的两种触发" tabindex="-1">二、重传的两种触发 <a class="header-anchor" href="#二、重传的两种触发" aria-label="Permalink to &quot;二、重传的两种触发&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 超时重传（RTO）</span></span>
<span class="line"><span>   发出去 &gt; 启动定时器 &gt; 超时还没收到 ACK &gt; 重传</span></span>
<span class="line"><span>   问题：RTO 怎么定？</span></span>
<span class="line"><span>     太长：丢包后干等，慢</span></span>
<span class="line"><span>     太短：没丢也重传，浪费带宽</span></span>
<span class="line"><span>   做法：动态估算 RTT（加权平均 + 偏差），RTO = SRTT + 4 × RTTVAR（Jacobson 算法）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>② 快速重传（Fast Retransmit）</span></span>
<span class="line"><span>   收到 3 个重复 ACK（都 ack=1001）&gt; 说明 1001 那段丢了</span></span>
<span class="line"><span>   &gt; 不等超时，立刻重传</span></span>
<span class="line"><span>   为什么是 3 个：1~2 个可能只是乱序，3 个基本可以确定是丢了</span></span></code></pre></div><p><strong>SACK（选择性确认）</strong>：ACK 里带上&quot;我还收到了 2000~3000&quot;，这样发送方知道只丢了一段，可以只重传那一段，不用把后面的全部重发。</p><h3 id="三、滑动窗口-流量控制" tabindex="-1">三、滑动窗口：流量控制 <a class="header-anchor" href="#三、滑动窗口-流量控制" aria-label="Permalink to &quot;三、滑动窗口：流量控制&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>已发已确认 | 已发未确认 | 可发未发 | 不可发</span></span>
<span class="line"><span>           |&lt;------ 窗口大小（接收方通告）------&gt;|</span></span></code></pre></div><p><strong>三个要点</strong>：</p><ol><li><strong>窗口大小由接收方决定</strong>，反映&quot;我的接收缓冲区还剩多少&quot;。这叫<strong>流量控制</strong>——防止快的发送方淹没慢的接收方。</li><li><strong>窗口滑动</strong>：收到 ACK 后，窗口右移，新数据可以发。</li><li><strong>零窗口</strong>：接收方缓冲区满了，通告 <code>window=0</code>，发送方停止发送，并周期性发<strong>窗口探测</strong>（避免死等，因为窗口更新的 ACK 可能丢）。</li></ol><p><strong>糊涂窗口综合征（SWS）</strong>：如果接收方每次只腾出 1 字节就通告，发送方就每次只发 1 字节，效率极低。</p><ul><li>接收方解法：窗口小于某阈值（min(MSS, 缓冲区一半)）时，不通告，等攒够再说。</li><li>发送方解法：Nagle 算法——小数据攒够一个 MSS 或收到 ACK 再发。</li></ul><h3 id="四、nagle-算法与延迟确认-两个-优化-打架" tabindex="-1">四、Nagle 算法与延迟确认（两个&quot;优化&quot;打架） <a class="header-anchor" href="#四、nagle-算法与延迟确认-两个-优化-打架" aria-label="Permalink to &quot;四、Nagle 算法与延迟确认（两个&quot;优化&quot;打架）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Nagle：小包先攒着，等凑够 MSS 或收到前一个的 ACK 再发  &gt; 减少小包数量</span></span>
<span class="line"><span>延迟确认：收到数据不立刻 ACK，等 200ms 看看有没有数据要捎带  &gt; 减少 ACK 数量</span></span>
<span class="line"><span></span></span>
<span class="line"><span>冲突：Nagle 等 ACK 才发，延迟确认等 200ms 才回 ACK</span></span>
<span class="line"><span>     &gt; 每个小包都要多等 200ms &gt; 典型的&quot;40ms/200ms 延迟&quot;问题</span></span></code></pre></div><p><strong>解法</strong>：<code>TCP_NODELAY</code> 关掉 Nagle。<strong>对延迟敏感的协议（Redis、游戏、RPC）都应该关</strong>。</p><h3 id="五、拥塞控制-四个阶段" tabindex="-1">五、拥塞控制：四个阶段 <a class="header-anchor" href="#五、拥塞控制-四个阶段" aria-label="Permalink to &quot;五、拥塞控制：四个阶段&quot;">​</a></h3><p>拥塞控制维护一个 <strong>cwnd（拥塞窗口）</strong>，实际发送窗口 = <code>min(cwnd, 接收方通告窗口)</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cwnd</span></span>
<span class="line"><span> |</span></span>
<span class="line"><span> |            ╱╲                      ╱╲</span></span>
<span class="line"><span> |           ╱  ╲                    ╱  ╲</span></span>
<span class="line"><span> |    慢启动 ╱    ╲ 拥塞避免         ╱    ╲</span></span>
<span class="line"><span> |    （指数）╱      ╲（线性+1）      ╱      ╲</span></span>
<span class="line"><span> |         ╱        ╲              ╱        ╲</span></span>
<span class="line"><span> |        ╱          ╲____________╱          ╲___</span></span>
<span class="line"><span> |       ╱            ^丢包&gt;减半          ^超时&gt;降到1</span></span>
<span class="line"><span> +------+----------------------------------------&gt; 时间</span></span>
<span class="line"><span>        ^ ssthresh</span></span></code></pre></div><table tabindex="0"><thead><tr><th>阶段</th><th>行为</th><th>触发</th></tr></thead><tbody><tr><td><strong>慢启动</strong></td><td>cwnd 从 1 开始，<strong>每收到一个 ACK 就 +1</strong>（指数增长，每个 RTT 翻倍）</td><td>连接开始 / 超时后</td></tr><tr><td><strong>拥塞避免</strong></td><td>cwnd 超过 ssthresh 后，<strong>每个 RTT +1</strong>（线性增长）</td><td>cwnd ≥ ssthresh</td></tr><tr><td><strong>快速重传</strong></td><td>收到 3 个重复 ACK，立刻重传丢失段</td><td>3 dup ACK</td></tr><tr><td><strong>快速恢复</strong></td><td>ssthresh = cwnd/2，cwnd = ssthresh（不回到 1）</td><td>快速重传后</td></tr></tbody></table><p><strong>关键区分</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>超时（RTO）     &gt; 认为网络严重拥塞 &gt; cwnd 直接降到 1，重新慢启动</span></span>
<span class="line"><span>3 个重复 ACK   &gt; 认为只是轻微丢包 &gt; cwnd 减半，快速恢复（不回到 1）</span></span></code></pre></div><p><strong>为什么区别对待</strong>：超时说明&quot;连 ACK 都回不来&quot;，网络可能真的堵死了；重复 ACK 说明&quot;后面的包能到，只是中间丢了一个&quot;，网络还好。</p><h3 id="六、几代拥塞控制算法" tabindex="-1">六、几代拥塞控制算法 <a class="header-anchor" href="#六、几代拥塞控制算法" aria-label="Permalink to &quot;六、几代拥塞控制算法&quot;">​</a></h3><table tabindex="0"><thead><tr><th>算法</th><th>思路</th><th>问题</th></tr></thead><tbody><tr><td><strong>Tahoe</strong></td><td>丢包就回 1</td><td>太保守</td></tr><tr><td><strong>Reno</strong></td><td>加入快速恢复</td><td>高延迟高带宽下增长太慢</td></tr><tr><td><strong>CUBIC</strong>（Linux 默认）</td><td>用三次函数增长，与 RTT 无关</td><td>仍以&quot;丢包&quot;为拥塞信号</td></tr><tr><td><strong>BBR</strong>（Google）</td><td>不看丢包，看<strong>带宽和 RTT</strong>，主动探测</td><td>需要更多工程调优，公平性有争议</td></tr></tbody></table><p><strong>为什么 BBR 是革命性的</strong>：传统算法把&quot;丢包&quot;当拥塞信号，但在<strong>高带宽、有一定丢包率</strong>的链路上（比如跨国、卫星），丢包不代表拥塞，传统算法会误判并降速。BBR 直接测量瓶颈带宽和最小 RTT，不依赖丢包。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果没有滑动窗口" tabindex="-1">反事实 1：如果没有滑动窗口 <a class="header-anchor" href="#反事实-1-如果没有滑动窗口" aria-label="Permalink to &quot;反事实 1：如果没有滑动窗口&quot;">​</a></h3><p>每发一个段就停下等 ACK（停等协议）。在 RTT=100ms 的链路上，每秒最多发 10 个段 × 1460 字节 = 14.6 KB/s。<strong>这就是&quot;带宽再大也没用&quot;的典型</strong>——吞吐量被 RTT 卡死。</p><p>滑动窗口让&quot;在途数据&quot;可以有很多，吞吐量 ≈ 窗口大小 / RTT。</p><h3 id="反事实-2-如果没有拥塞控制" tabindex="-1">反事实 2：如果没有拥塞控制 <a class="header-anchor" href="#反事实-2-如果没有拥塞控制" aria-label="Permalink to &quot;反事实 2：如果没有拥塞控制&quot;">​</a></h3><p>所有人全速发送 &gt; 中间路由器队列溢出 &gt; 大量丢包 &gt; 所有人重传 &gt; 更堵 &gt; <strong>拥塞崩溃</strong>（1986 年互联网真的发生过，吞吐量从 32Kbps 掉到 40bps）。</p><p>拥塞控制是&quot;<strong>所有 TCP 连接的集体自律</strong>&quot;——没有人强制，但大家都降速，网络才能用。</p><h3 id="反事实-3-如果窗口只看接收方-不看网络" tabindex="-1">反事实 3：如果窗口只看接收方，不看网络 <a class="header-anchor" href="#反事实-3-如果窗口只看接收方-不看网络" aria-label="Permalink to &quot;反事实 3：如果窗口只看接收方，不看网络&quot;">​</a></h3><p>发送方按接收方的 1MB 窗口全速发，但中间链路只有 100Kbps &gt; 路由器缓冲区被塞满 &gt; 大量丢包 &gt; 重传 &gt; 更糟。所以必须同时受 cwnd 限制。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：TCP 怎么保证可靠传输？</strong></p><blockquote><p>三条：<strong>序号</strong>（每个字节编号，能发现缺失）、<strong>确认</strong>（累积 ACK）、<strong>重传</strong>（超时 + 3 次重复 ACK 触发快速重传）。 <strong>加分</strong>：提到 SACK 减少不必要的重传，以及&quot;可靠不等于不丢，是丢了能补&quot;。</p></blockquote><p><strong>Q：流量控制和拥塞控制的区别？</strong></p><blockquote><p><strong>流量控制是端到端的</strong>：接收方告诉发送方&quot;我缓冲区还剩多少&quot;，防止发送方发太快导致接收方处理不过来。用<strong>滑动窗口</strong>实现。 <strong>拥塞控制是全局的</strong>：发送方推测&quot;网络堵不堵&quot;，主动限速，防止把整个网络压垮。用<strong>cwnd</strong>实现。 一句话：<strong>一个怕对方收不下，一个怕路上堵死</strong>。实际发送窗口 = min(两者)。</p></blockquote><p><strong>Q：慢启动为什么叫&quot;慢&quot;？</strong></p><blockquote><p>因为它从 cwnd=1 开始（很小的窗口），但<strong>增长是指数的</strong>（每个 RTT 翻倍）。&quot;慢&quot;指的是起点低，不是速度慢。 这是经典陷阱题，答&quot;因为它增长慢&quot;就错了。</p></blockquote><p><strong>Q：超时重传和快速重传有什么区别？</strong></p><blockquote><p>超时是&quot;连 ACK 都没回来&quot;，判断为严重拥塞，cwnd 降到 1。 快速重传是&quot;收到 3 个重复 ACK&quot;，说明只是个别丢包，cwnd 减半即可。 <strong>区别对待的本质</strong>：一个是&quot;路断了&quot;，一个是&quot;掉了个包裹&quot;。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP 怎么保证不丢？</span></span>
<span class="line"><span>  &gt; 靠什么发现丢了？（序号 + 累积 ACK）</span></span>
<span class="line"><span>    &gt; 怎么触发重传？（超时 / 3 个重复 ACK）</span></span>
<span class="line"><span>      &gt; 3 个为什么不是 1 个？（乱序也会产生重复 ACK，3 个才足够确定）</span></span>
<span class="line"><span>        &gt; 重传全部还是只重传丢的？（SACK &gt; 只重传丢失段）</span></span>
<span class="line"><span>          &gt; 发多快？（窗口）</span></span>
<span class="line"><span>            &gt; 窗口受谁限制？（接收方窗口 + 拥塞窗口，取小）</span></span>
<span class="line"><span>              &gt; 拥塞窗口怎么变？（慢启动 / 拥塞避免 / 快恢复）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/network/02">TCP 连接管理：三次握手、四次挥手、TIME_WAIT</a>：握手时协商 MSS 和初始窗口，是这里的基础</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/04">HTTP / HTTPS 与缓存</a>：HTTP/2 的多路复用解决了&quot;应用层队头阻塞&quot;，但 <strong>TCP 层的队头阻塞还在</strong>——这是 HTTP/3 改用 QUIC（基于 UDP）的根本原因</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/os/04">IO 模型与零拷贝：等设备的时候，CPU 在干什么</a>：socket 缓冲区大小直接影响窗口通告值</li><li><strong>&gt; 影响</strong> 工程实践：CDN 就近接入是为了减小 RTT（窗口增长更快）；长肥管道（高带宽高延迟）场景下窗口大小是瓶颈</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么慢启动不叫&quot;快启动&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为它从<strong>一个 MSS 的小窗口</strong>开始，起点很低。虽然增长速度是<strong>指数</strong>的（每个 RTT 翻倍），但名字强调的是&quot;<strong>从很小的值慢慢起步</strong>&quot;这个动作。</p><p>如果叫&quot;快启动&quot;会让人以为一上来就全速发——那就直接拥塞崩溃了。</p><p>顺便记：慢启动的&quot;慢&quot;是针对&quot;初始窗口&quot;而言，和&quot;增长速度&quot;无关。这是面试最爱的文字陷阱。</p></details><p><strong>Q2：TCP 的队头阻塞是什么？为什么 HTTP/2 解决不了？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p><strong>TCP 层</strong>：TCP 保证&quot;按序交付&quot;。如果第 1001~1460 字节的段丢了，即使后面 1461~100000 的段都到了，<strong>也必须等那一段重传成功</strong>才能交给应用层。这就是队头阻塞（HOL blocking）。</p><p><strong>HTTP/2 的多路复用</strong>：在<strong>一个 TCP 连接</strong>上跑多个流，解决了 HTTP/1.1 的&quot;应用层队头阻塞&quot;（一个请求卡住不影响其他请求的发送）。</p><p><strong>但</strong>：所有流共享同一个 TCP 连接，一旦底层丢了一个段，<strong>所有流都要等</strong>——TCP 层的队头阻塞没解决，反而因为多路复用而被放大了（一个丢包卡住所有请求）。</p><p><strong>HTTP/3 的解法</strong>：改用 QUIC（基于 UDP），在<strong>用户态</strong>实现可靠传输，每个流独立排序，一个流丢包不影响其他流。</p></details><p><strong>Q3：发送窗口到底由什么决定？</strong></p><details class="details custom-block"><summary>点开看答案</summary><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>实际发送窗口 = min(接收方通告窗口 rwnd, 拥塞窗口 cwnd)</span></span></code></pre></div><ul><li><code>rwnd</code> 由<strong>接收方</strong>根据自己缓冲区剩余空间决定，防止接收方被淹没。</li><li><code>cwnd</code> 由<strong>发送方</strong>根据网络拥塞情况估算，防止网络被压垮。</li></ul><p>两个都要满足：<strong>哪怕接收方说&quot;我能收 1MB&quot;，如果网络只允许 10KB，也只能发 10KB</strong>；反过来，网络很空但接收方缓冲区满了，也得停。</p><p>这就是&quot;端到端 + 全局&quot;两层限制的交汇点。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;寄书&quot;类比会让人以为可以乱序收</strong>。TCP 对应用层是<strong>严格有序的字节流</strong>，乱序到达的段会在接收缓冲区里排队等待，不会交给应用。</li><li><strong>&quot;可靠&quot;不等于&quot;一定送达&quot;</strong>。TCP 保证&quot;要么完整送达，要么连接断开让你知道&quot;，不保证&quot;一定能送&quot;。断网了它也没办法。</li><li><strong>累积 ACK 的副作用</strong>：只回一个 <code>ack=1001</code>，发送方无法知道 1001 之后有没有收到——这就是 SACK 存在的理由。</li><li><strong>Nagle 和延迟确认是&quot;两个优化互相打架&quot;的经典案例</strong>。默认开启 Nagle 在某些场景会造成 40ms 延迟，所以对延迟敏感的服务要设 <code>TCP_NODELAY</code>。</li><li><strong>拥塞控制是&quot;礼貌&quot;，不是&quot;强制&quot;</strong>。不遵守的流（比如 UDP 洪水）会挤占遵守者的带宽——这是网络公平性的根本难题。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能说出可靠传输的三根支柱（序号 / 确认 / 重传），并解释累积 ACK 的含义</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能区分超时重传和快速重传的触发条件与不同处理（cwnd 降到 1 vs 减半）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能画出滑动窗口的示意，并说清&quot;窗口由谁决定&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能准确说出流量控制和拥塞控制的区别（一个怕对方收不下，一个怕路上堵）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能解释慢启动为什么叫&quot;慢&quot;（起点低，不是增长慢）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能说出 TCP 队头阻塞的成因，以及 HTTP/2 为什么解决不了、HTTP/3 怎么解决</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 能解释 Nagle 与延迟确认的冲突，以及什么时候该关 Nagle</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="7"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,66)])])}const h=s(e,[["render",l]]);export{u as __pageData,h as default};
